def tr(text: str, language: str = "pt-BR") -> str:
    """Translate an app-owned UI string; transcript and user data should bypass this."""
    if language != "en":
        return text
    if text in TRANSLATIONS:
        return TRANSLATIONS[text]
    if text.startswith('O dicionário pode ter no máximo ') and text.endswith(' regras.'):
        return 'Dictionary can contain at most ' + text[len('O dicionário pode ter no máximo '):-len(' regras.')] + ' rules.'
    if text.startswith("Linha "):
        for suffix, translated in TRANSLATIONS.items():
            if text.endswith(suffix) and suffix in ("use o formato 'original = substituição'.", "origem e substituição precisam ter conteúdo.", "origem duplicada."):
                return "Line " + text[len("Linha "): -len(suffix)] + translated
    if text.startswith("Linha ") and "cada campo pode ter no máximo " in text:
        before, after = text.split("cada campo pode ter no máximo ", 1)
        return "Line " + before[len("Linha "):] + "each field can contain at most " + after.replace(" caracteres.", " characters.")
    for prefix, translated in TRANSLATIONS.items():
        if (prefix.endswith(": ") or prefix.endswith(" · ")) and text.startswith(prefix):
            remainder = text[len(prefix):]
            if remainder.endswith(" s após parar"):
                remainder = remainder[:-len(" s após parar")] + " s after stopping"
            return translated + remainder
    return text
